/**
 * Locked experiment parameters.
 *
 * This file replaces the reference experiment's `control-panel.html` runtime override
 * mechanism. Values here are draft-pre-registration-grade — once the draft
 * is filed, the deployed commit SHA will match the OSF record. While the
 * document remains a draft, edits to this file are made in lockstep with
 * `pre-reg/pre-reg.json#config_locked` (the byte-equality test enforces
 * agreement between the two) and are recorded as design revisions in
 * `BUILD_LOG.md`. After registration, any change here will require a
 * post-registration amendment in addition to a `schema_version` bump.
 *
 * Anchors to the design doc (Follow-Up_Experiment_Design.md):
 *   §3.1  visual frame; §3.2 tone bank; §3.4 dummies; §3.5 apparatus
 *   §4    five trial types, set size 3 (revised 4 → 3 on 2026-05-08)
 *   §6.2  four canonical probe types (T_on, T_off, F_on, F_off)
 *   §7    slot timing (1500 ms memory slot; 3000 ms star window)
 *   §8.1  run-length cap = 2 within trial
 *   §10   run-length cap = 2 across trial types
 *   §11   block structure
 */

export const config = Object.freeze({
  schema_version: '1.2.0',
  build_id: 'step19-bucketed-upload',

  /* Localisation — see design §15 q5. English ships for the main Prolific batch. */
  locale: 'en',

  /* PRNG — every counterbalance step consumes from a single seeded Mulberry32 instance. */
  prng: {
    /* If null, seed is hashed from PROLIFIC_PID at session start. */
    deterministic_override: null,
  },

  /* Visual frame — design §3.1.
   *
   * Cell size is mirrored from the round-1 reference experiment
   * (`Orientations-Unpackaged-Amir's-finished/control-panel.html`,
   * default `gridSize: 190 px` → 5×5 cells of 38 px ≈ 10 mm @ 96 DPI).
   * The pre-lock value of 38 mm produced an oversized grid on most
   * monitors (~190 mm = 7.5 inches edge-to-edge); 10 mm gives the
   * 50 mm / ~190 px reference layout. */
  grid: {
    cells_per_side: 5,
    cell_size_mm: 10,
    centre_cell_index: 12,
    rotation_min_deg: -90,
    rotation_max_deg: 90,
  },

  /* Imagery pattern — design §3.1, hard-coded per domain non-negotiable #1 */
  pattern: {
    gray_pattern_cells: Object.freeze([1, 2, 3, 7, 10, 11, 12, 13, 14, 17, 21, 22, 23]),
    pattern_phase_duration_ms: 4000,
    pattern_phase_frequency_trials: 8,
  },

  /* Tone bank — design §3.2; audio-only; never rendered visually.
   *
   * The original chromatic spec (`220 × 2^((k−1)/12)`, A3..G♯5) was replaced
   * because every tone landed on a named pitch class, exposing the bank to
   * note-name re-encoding by musically trained participants — a strategy
   * confound the analyst cannot disentangle from genuine auditory WM.
   *
   * Replacement spec (draft revision 2026-05-05): 24 sine tones
   * **logarithmically spaced** between `low_freq_hz` and `high_freq_hz`.
   * Anchor band 200–3900 Hz follows Li, Cowan & Saults (2013, APP 75(1),
   * pp. 150–151) — chosen because (i) Sek & Moore (1995, J. Acoust. Soc. Am.
   * 97(4), 2479–2486) report similar frequency difference limens across this
   * range so all 24 tones sit in a regime of comparable pitch acuity, and
   * (ii) Li et al. demonstrated this band can be filled with non-musical sine
   * tones that resist octave-equivalence chunking (Shepard 1982). At 24
   * tones the neighbour ratio is `(3900/200)^(1/23) ≈ 1.139` (~13.9 %),
   * distinct from any Western interval (semitone 5.9 %, whole-tone 12.25 %,
   * minor third 18.92 %, major third 25.99 %, fifth 49.83 %); see
   * `tests/tones.test.js` for the no-near-harmonic and no-near-musical-step
   * invariants pinned across the bank. The cell↔tone bijection in
   * `src/audio/tones.js` is unchanged — only the frequency table is reseated
   * onto a non-musical ladder.
   *
   * Envelope (duration 350 ms, 10 ms cosine ramp) is unchanged from the
   * prior pilot because the 1500 ms slot in design §6.2 is built around it
   * (350 ms tone + 1150 ms silence). Li's slightly longer 500 ms / 25 ms
   * envelope is informative but not load-bearing for non-musicality.
   *
   * Equal-loudness compensation (draft revision 2026-05-05; target raised
   * from 60 to 70 phons by the 2026-05-07 draft revision). The
   * per-tone digital amplitude is scaled by 10^(comp_dB/20), where
   * comp_dB is the dB difference between the SPL needed at the tone's
   * frequency and the SPL needed at 1 kHz to elicit the same loudness
   * in phons (ISO 226:2003 Annex A, `target_phon_level: 70`). Across
   * 200–3900 Hz the correction ranges from ≈ +7 dB at the low end to
   * ≈ −4 dB near the ear's 2.5–3 kHz sensitivity peak; with the
   * default 0.25 peak (≈ −12 dBFS) the worst-case boosted peak is
   * ≈ 0.56, well below the 0.95 clipping margin. See
   * `src/audio/equal-loudness.js` for the tabulated lookup. */
  tones: {
    count: 24,
    low_freq_hz: 200,
    high_freq_hz: 3900,
    duration_ms: 350,
    cosine_ramp_ms: 10,
    target_db_spl: 70,
    target_phon_level: 70,
  },

  /* Dummies — design §3.4. Side length scales with cell_size_mm (10 mm) at
   * the same ~0.5 cell ratio used in the round-1 reference (5 mm side =
   * star bounding diameter). The open-square stroke is specified in mm
   * (not px) because the SVG viewBox is in mm — the round-1 reference's
   * 2 px stroke at ~3.78 px/mm ≈ 0.53 mm; we round up slightly to 0.4 mm
   * so the contour is still visible after browser stroke-rounding.
   *
   * Step 13.17 design lock — the dummy primitive switched from an open
   * circle to an open square. The square's per-slot envelope follows the
   * "single-task dummy stands in for the matched dual-task condition's
   * other modality" rule:
   *   - D-only / T-only dummies stand in for the matched I+D / I+T
   *     condition's STAR, and therefore run on the S-slot envelope
   *     (3000 ms visible + 500 ms empty-circle offset = 3500 ms).
   *   - I-only dummies stand in for the matched I+D / I+T condition's
   *     MEMORY ITEM (dot or tone), and therefore run on the M-slot
   *     envelope (1000 ms visible + 500 ms empty-circle offset = 1500
   *     ms) — the same envelope a dot occupies in I+D and a tone in I+T.
   * Per-slot timing is therefore byte-identical between each single-task
   * condition and the dual-task condition it stands in for. The visible
   * portion is irrelevant for the participant (live dummies are mounted
   * with `visible: false`); the timing rule is purely a temporal-equating
   * device. */
  dummies: {
    open_square_size_mm: 5,
    open_square_stroke_mm: 0.4,
    ghost_dot_opacity: 0.6,
    ghost_dot_diameter_mm: 5,
  },

  /* Memory items — design §6 */
  memory: {
    set_size: 3,
    dot_diameter_mm: 5,
    dot_duration_ms: 1000,
    inter_stimulus_interval_ms: 500,
    retention_interval_ms: 2000,
  },

  /* Imagery probes — design §5. `rotation_arrow_size_px` is a CSS-px size
   * (the arrow renders as an HTML <img>, not an SVG primitive on the mm
   * grid), matched to the round-1 reference's `arrow-display { width:
   * 100px }`.
   *
   * Imagination period (`imagination_duration_ms`, 2026-05-08 design lock):
   * the empty-circle hold between the arrow cue and the encoding rotation
   * is fixed at 5000 ms. During this window the participant has the
   * rotation angle in mind from the arrow cue and uses the time to
   * pre-imagine the rotated 13-cell pattern. The window is fixed (no
   * input, no auto-pass-on-keypress) so encoding-onset is identical
   * within and across imagery-bearing trial types.
   *
   * Star feedback is now synchronous on keypress — the previous
   * `feedback_latency_ms: 600` was retired in the same revision because
   * a 600 ms gap between the response and the green/red recolour read
   * to pilot participants as "the program took a while to register my
   * answer". With latency 0 the recolour happens on the same frame as
   * the keypress, matching the dot/tone probe path. */
  imagery: {
    stars_per_trial: 3,
    star_size_mm: 5,
    star_duration_ms: 3000,
    inter_star_interval_ms: 500,
    imagination_duration_ms: 5000,
    rotation_animation_ms: 500,
    post_rotation_delay_ms: 1000,
    rotation_arrow_size_px: 100,
  },

  /* Recognition probes — design §6.3.
   *
   * The 3000 ms response window matches the manuscript spec and the
   * instruction copy ("you will have 3 seconds for each test"). Answered
   * probes now stay on screen for the rest of that 3000 ms onset, with the
   * feedback colour shown on the still-visible dot or question mark. The
   * same 500 ms value below also serves as the shared post-stimulus offset
   * after the onset ends, and the only gap between successive probes (no
   * separate inter-probe interval — Step 16 design lock). */
  probes: {
    response_window_ms: 3000,
    feedback_duration_ms: 500,
  },

  /* Counterbalance & sequencing — design §8.1, §9, §10 */
  sequencing: {
    /* Within-trial M/S sequence run-length cap (design §8.1).
     * Maximum allowed run of consecutive M (or S) slots. cap = 2 → runs of
     * length 2 are OK, length 3 is rejected. */
    within_trial_run_length_cap: 2,
    /* Across-trial trial-type run-length cap (design §10).
     * "No more than 2 trials of the same type in a row" — primary spec.
     * Design notes the cap may be relaxed to 3 if pilot pacing is hectic. */
    between_trial_run_length_cap: 2,
  },

  /* Block structure — design §11 */
  blocks: {
    practice_trials_per_type: 2,
    main_trials_per_type: 24,
    /* The 24 main trials of each type are split across two main blocks (12 + 12). */
    main_block_count: 2,
    rest_duration_s: 30,
  },

  /* Practice gating — design §11.3 */
  practice: {
    accuracy_criterion: 0.7,
    max_loops: 1,
  },

  /* Anticipatory-response cutoff for analysis (logged but not enforced at collection). */
  rt_cutoff_ms: 250,

  /* Attention checks — design §11.4 */
  attention_checks: {
    instruction_typed_count: 3,
    instruction_max_failures: 1,
  },

  /* Prolific & data flow — design §3.5 */
  prolific: {
    /* The completion URL is participant-specific; this is the placeholder template
     * that gets the participant's completion code substituted at session end.
     * Replace with the actual Prolific completion URL when the study is published. */
    completion_url: 'https://app.prolific.com/submissions/complete?cc=CJAH0B0X',
  },

  /* Data egress — DataPipe (https://pipe.jspsych.org), jsPsych's free
   * forwarding service into an OSF project. At session end the uploader
   * partitions every captured row into the canonical 10-bucket layout
   * (`src/uploader.js#BUCKETS`) and POSTs one DataPipe envelope per
   * non-empty bucket. DataPipe writes one OSF file per envelope, named
   * `<session_id>__<NN_label>.json` (e.g. `<sid>__03_d_only.json`). A
   * complete session therefore yields up to 10 OSF files: consent +
   * demographics, practice, d_only, i_only (= "star-only"), t_only, i_t
   * (= "dual tone+star"), i_d (= "dual dot+star"), music questionnaire,
   * strategy questionnaire, and a meta bucket for everything else
   * (calibration, instructions, demos, fullscreen events, pattern phases,
   * etc.). The two-digit prefix is so an OSF directory listing sorts in
   * canonical reading order without manual sort.
   *
   * Why bucketed instead of chunk-streamed (revised 2026-05-16): the round-1
   * design POSTed many small per-chunk files during the session, giving
   * crash-resilient incremental upload at the cost of needing a separate
   * reassembly pass before analysis. The follow-up uses a fixed file layout
   * keyed to the analysis units (one file per condition, one per
   * questionnaire) so a downloaded OSF folder is already analysis-ready.
   * Buffering everything client-side until session end is acceptable because
   * (i) the storage layer persists every row to IndexedDB immediately, so a
   * crash before upload still yields a recoverable local download, and
   * (ii) the analyst's first question is always "which condition?", not
   * "which time-slice?".
   *
   * `datapipe_experiment_id` must be replaced with the alphanumeric ID
   * minted on the DataPipe dashboard for this study. Until it is, the
   * uploader detects the `PLACEHOLDER` token and falls through to the JSON
   * download fallback (same path as `endpoint: null` did historically), so a
   * pilot or dev session can still finish without losing data. */
  uploader: {
    endpoint: 'https://pipe.jspsych.org/api/data/',
    provider: 'datapipe',
    datapipe_experiment_id: 'YdaKHf3W2XX7',
    retry_max: 5,
    retry_initial_backoff_ms: 1000,
  },
});
